                    "-apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif",
                  fontWeight: 500,
                }}
              >
                {name}
              </span>
            )}
          </span>
          {children as React.ReactNode}
        </span>
      );
    }

    return children;
  };
}

function pathEquals(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

/**
 * Compute intersection of two ranges, returning null if they don't overlap.
 * Uses SlateRange.intersection when both ranges are valid, with a try/catch
 * to handle edge cases where paths don't exist in the document.
 */
function safeIntersection(nodeRange: Range, cursorRange: Range): Range | null {
  try {
    return SlateRange.intersection(nodeRange, cursorRange);
  } catch {
    return null;
  }
}

import { useEffect, useState } from 'react';
import { useYooptaEditor } from '@yoopta/editor';

import type { CollaborationYooEditor, RemoteCursorData } from '../types';
import './remote-cursors.css';

/**
 * Renders remote user cursors.
 *
 * Single-block cursors (caret + text selection) are rendered via the Slate
 * `decorate` / `renderLeaf` pipeline registered by `withCollaboration`.
 *
 * Multi-block selection overlays (which span multiple Slate editors) are
 * still rendered here as fixed-position DOM overlays.
 *
 * Must be used as a child of <YooptaEditor>.
 */
export const RemoteCursors = () => {
  const editor = useYooptaEditor() as CollaborationYooEditor;
  const [cursors, setCursors] = useState<RemoteCursorData[]>([]);
  const [, forceUpdate] = useState(0);

  useEffect(() => {
    if (!editor.collaboration) return;

    const handler = (payload: RemoteCursorData[]) => {
      setCursors(payload);
    };

    (editor as any).on('collaboration:cursors-change', handler);
    return () => {
      (editor as any).off('collaboration:cursors-change', handler);
    };
  }, [editor]);

  // Filter to only multi-block selections
  const multiBlockCursors = cursors.filter(
    (c) => c.selectedBlocks && c.selectedBlocks.length > 1,
  );

  // Re-render on scroll so multi-block overlay positions update
  useEffect(() => {
    if (multiBlockCursors.length === 0) return;

    const editorEl = editor.refElement;
    if (!editorEl) return;

    const scrollParent = findScrollParent(editorEl);

    const onScroll = () => forceUpdate((n) => n + 1);
    scrollParent.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('scroll', onScroll, { passive: true });

    return () => {
      scrollParent.removeEventListener('scroll', onScroll);
      window.removeEventListener('scroll', onScroll);
    };
  }, [editor, multiBlockCursors.length]);

  if (multiBlockCursors.length === 0) return null;

  return (
    <div className="yoopta-collab-cursors-container">
      {multiBlockCursors.map((cursor) => (
        <MultiBlockSelection
          key={cursor.clientId}
          selectedBlocks={cursor.selectedBlocks!}
          user={cursor.user}
          editor={editor}
        />
      ))}
    </div>
  );
};

// ---- Multi-block selection ----

type MultiBlockSelectionProps = {
  selectedBlocks: number[];
  user: RemoteCursorData['user'];
  editor: CollaborationYooEditor;
};

const MultiBlockSelection = ({ selectedBlocks, user, editor }: MultiBlockSelectionProps) => {
  const editorRect = editor.refElement?.getBoundingClientRect();
  if (!editorRect) return null;

  // Find block IDs for the selected orders
  const blockEntries = Object.values(editor.children);
  const selectedBlockIds = selectedBlocks
    .map((order) => blockEntries.find((b) => b.meta.order === order)?.id)
    .filter(Boolean) as string[];

  if (selectedBlockIds.length === 0) return null;

  // Get bounding rects for all selected blocks
  const rects = selectedBlockIds
    .map((id) => {
      const el = document.querySelector(`[data-yoopta-block-id="${id}"]`);
      return el?.getBoundingClientRect() ?? null;
    })
    .filter(Boolean) as DOMRect[];

  if (rects.length === 0) return null;

  const labelOnFirst = rects[0];

  return (
    <>
      {rects.map((rect, i) => (
        <div
          key={selectedBlockIds[i]}
          className="yoopta-collab-multi-block-highlight"
          style={{
            position: 'fixed',
            top: rect.top,
            left: rect.left,
            width: rect.width,
            height: rect.height,
            backgroundColor: user.color,
            opacity: 0.08,
            pointerEvents: 'none',
            borderRadius: '2px',
            zIndex: 49,
          }}
        />
      ))}

      {/* Name label on the first selected block */}
      <CursorLabel
        user={user}
        style={{
          position: 'fixed',
          top: labelOnFirst.top - 20,
          left: labelOnFirst.left,
          zIndex: 51,
        }}
      />

      {/* Left accent bar spanning all blocks */}
      <div
        className="yoopta-collab-multi-block-bar"
        style={{
          position: 'fixed',
          top: rects[0].top,
          left: rects[0].left - 4,
          width: 3,
          height: rects[rects.length - 1].bottom - rects[0].top,
          backgroundColor: user.color,
          borderRadius: '2px',
          pointerEvents: 'none',
          zIndex: 50,
        }}
      />
    </>
  );
};

// ---- Shared label component ----

type CursorLabelProps = {
  user: RemoteCursorData['user'];
  style?: React.CSSProperties;
};

const CursorLabel = ({ user, style }: CursorLabelProps) => (
  <span
    className="yoopta-collab-cursor-label"
    style={{
      backgroundColor: user.color,
      color: '#fff',
      fontSize: '11px',
      padding: '1px 6px',
      borderRadius: '3px',
      whiteSpace: 'nowrap',
      lineHeight: '16px',
      userSelect: 'none',
      pointerEvents: 'none',
      ...style,
    }}
  >
    {user.name}
  </span>
);

// ---- Utilities ----

function findScrollParent(el: HTMLElement): HTMLElement | Window {
  let parent = el.parentElement;
  while (parent) {
    const { overflow, overflowY } = getComputedStyle(parent);
    if (overflow === 'auto' || overflow === 'scroll' || overflowY === 'auto' || overflowY === 'scroll') {
      return parent;
    }
    parent = parent.parentElement;
  }
  return window;
}

import { useEffect } from "react";
import { isMacOS } from "@/lib/platform";

const ALLOW_SELECTION_SELECTOR = [
  ".xterm",
  ".cm-editor",
  ".select-text",
  "[data-allow-text-selection='true']",
  "input",
  "textarea",
  "[contenteditable='true']",
  "[role='textbox']",
].join(",");

function isInsideAllowedSelectionArea(node: Node | null) {
  if (!node) return false;

  const element = node instanceof Element ? node : node.parentElement;
  return Boolean(element?.closest(ALLOW_SELECTION_SELECTOR));
}

function shouldKeepSelection(eventTarget: EventTarget | null) {
  if (eventTarget instanceof Node && isInsideAllowedSelectionArea(eventTarget)) {
    return true;
  }

  const selection = window.getSelection();
  if (!selection || selection.isCollapsed) return true;

  return (
    isInsideAllowedSelectionArea(selection.anchorNode) ||
    isInsideAllowedSelectionArea(selection.focusNode)
  );
}

function clearSelectionIfNeeded(eventTarget: EventTarget | null) {
  if (shouldKeepSelection(eventTarget)) return;

  const selection = window.getSelection();
  if (!selection || selection.isCollapsed) return;

  selection.removeAllRanges();
}

export function useMacSelectionGuard() {
  useEffect(() => {
    if (!isMacOS) return;

    const handleWheel = (event: WheelEvent) => {
      clearSelectionIfNeeded(event.target);
    };

    const handlePointerEnd = (event: PointerEvent) => {
      clearSelectionIfNeeded(event.target);
    };

    const handleMouseEnd = (event: MouseEvent) => {
      clearSelectionIfNeeded(event.target);
    };

    const handleBlur = () => {
      clearSelectionIfNeeded(document.activeElement);
    };

    const handleVisibilityChange = () => {
      if (document.visibilityState !== "visible") {
        clearSelectionIfNeeded(document.activeElement);
      }
    };

    document.addEventListener("wheel", handleWheel, {
      capture: true,
      passive: true,
    });
    document.addEventListener("pointerup", handlePointerEnd, true);
    document.addEventListener("pointercancel", handlePointerEnd, true);
    document.addEventListener("mouseup", handleMouseEnd, true);
    window.addEventListener("blur", handleBlur);
    document.addEventListener("visibilitychange", handleVisibilityChange);

    return () => {
      document.removeEventListener("wheel", handleWheel, true);
      document.removeEventListener("pointerup", handlePointerEnd, true);
      document.removeEventListener("pointercancel", handlePointerEnd, true);
      document.removeEventListener("mouseup", handleMouseEnd, true);
      window.removeEventListener("blur", handleBlur);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, []);
}

import fs from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";

const packageDir = path.resolve(
  process.cwd(),
  "node_modules",
  "@xterm",
  "xterm",
  "lib",
);

const cases = [
  {
    name: "ESM",
    file: "xterm.mjs",
    state:
      "this._nyatermWideCharMidpointSelection=this._enabled&&!e.shiftKey&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&e.detail===1",
    startFallback: ":this._model.selectionStart[0]++)",
    endFallback: ":this._model.selectionEnd[0]++)",
  },
  {
    name: "CJS",
    file: "xterm.js",
    state:
      "this._nyatermWideCharMidpointSelection=this._enabled&&!e.shiftKey&&!e.altKey&&!e.ctrlKey&&!e.metaKey&&1===e.detail",
    startFallback: ":this._model.selectionStart[0]++)",
    endFallback: ":this._model.selectionEnd[0]++)",
  },
] as const;

describe("xterm wide-character selection patch", () => {
  it.each(cases)(
    "$name keeps Shift/modified selection on xterm's original wide-cell behavior",
    ({ file, state, startFallback, endFallback }) => {
      const source = fs.readFileSync(path.join(packageDir, file), "utf8");
      const stateName = "_nyatermWideCharMidpointSelection";

      expect(source).toContain("/*nyaterm:wide-char-selection-midpoint*/");
      expect(source).toContain(state);
      expect(source.split(stateName)).toHaveLength(4);

      const startUse = source.indexOf(
        `this.${stateName}?this._model.selectionStart[0]+=`,
      );
      const endUse = source.indexOf(
        `this.${stateName}?this._model.selectionEnd[0]+=`,
      );
      expect(startUse).toBeGreaterThan(-1);
      expect(endUse).toBeGreaterThan(startUse);
      expect(source.slice(startUse, startUse + 500)).toContain(startFallback);
      expect(source.slice(endUse, endUse + 500)).toContain(endFallback);

      // The decision is captured once on mousedown. Mousemove must not switch
      // algorithms based on the modifier state of later events.
      expect(source).not.toContain("_activeSelectionMode===0&&!e.shiftKey?");
      expect(source).not.toContain(
        "0===this._activeSelectionMode&&!e.shiftKey?",
      );
    },
  );
});

import type { AiDocumentAnchor, AiHeadingAnchor, AiSelectionContext } from "./inline";

const maxSelectionSourceChars = 4000;

export function findSelectedHeading(
  selection: AiSelectionContext | null,
  headingAnchors: AiHeadingAnchor[] | undefined
) {
  if (!selection?.text.trim()) return null;

  const selectedText = normalizeSelectionText(selection.text);
  if (!selectedText) return null;

  return (headingAnchors ?? []).find((heading) => {
    if (selection.from < heading.from || selection.to > heading.to) return false;

    const title = normalizeSelectionText(heading.title);
    const markdown = normalizeSelectionText(formatHeadingMarkdown(heading));
    return selectedText === title || selectedText === markdown;
  }) ?? null;
}

export function findSelectionSection(
  selection: AiSelectionContext | null,
  sectionAnchors: AiDocumentAnchor[] | undefined
) {
  if (!selection) return null;

  return (sectionAnchors ?? [])
    .filter((section) => section.kind === "section")
    .filter((section) => selection.from >= section.from && selection.to <= section.to)
    .sort((left, right) => (left.to - left.from) - (right.to - right.from))[0] ?? null;
}

export function formatSelectionSourceContext({
  documentContent,
  headingAnchors,
  sectionAnchors,
  selection
}: {
  documentContent: string;
  headingAnchors?: AiHeadingAnchor[];
  sectionAnchors?: AiDocumentAnchor[];
  selection: AiSelectionContext | null;
}) {
  const source = resolveSelectionSourceContext({
    documentContent,
    headingAnchors,
    sectionAnchors,
    selection
  });
  if (!source) return [];

  return formatMarkdownSourceContext(source, "Markdown source context:");
}

export function formatMarkdownSourceContext(
  source: { from: number; markdown: string; to: number },
  label: string
) {
  return [
    `Markdown source range: ${source.from}-${source.to}`,
    label,
    "```markdown",
    source.markdown,
    "```"
  ];
}

export function resolveMarkdownSourceContext({
  documentContent,
  fallbackText,
  from,
  to
}: {
  documentContent: string;
  fallbackText?: string;
  from?: number;
  to?: number;
}) {
  const sourceFromDocument = markdownSliceFromDocument(documentContent, from, to);
  if (sourceFromDocument) return sourceFromDocument;

  const markdown = fallbackText?.trim();
  if (!markdown) return null;

  return {
    from: from ?? 0,
    markdown: truncateSourceMarkdown(markdown),
    to: to ?? markdown.length
  };
}

function resolveSelectionSourceContext({
  documentContent,
  headingAnchors,
  sectionAnchors,
  selection
}: {
  documentContent: string;
  headingAnchors?: AiHeadingAnchor[];
  sectionAnchors?: AiDocumentAnchor[];
  selection: AiSelectionContext | null;
}) {
  if (!selection) return null;

  const selectedHeading = findSelectedHeading(selection, headingAnchors);
  const selectionSection = findSelectionSection(selection, sectionAnchors);
  const range = selectedHeading ?? selectionSection ?? selection;
  return resolveMarkdownSourceContext({
    documentContent,
    fallbackText: "text" in range ? range.text : undefined,
    from: range.from,
    to: range.to
  });
}

function markdownSliceFromDocument(documentContent: string, from: number | undefined, to: number | undefined) {
  const clampedFrom = clampSourcePosition(from, documentContent.length);
  const clampedTo = clampSourcePosition(to, documentContent.length);
  if (clampedFrom === null || clampedTo === null) return null;
  const fromPosition = Math.min(clampedFrom, clampedTo);
  const toPosition = Math.max(clampedFrom, clampedTo);
  if (fromPosition >= toPosition) return null;

  const markdown = documentContent.slice(fromPosition, toPosition).trim();
  if (!markdown) return null;

  return {
    from: fromPosition,
    markdown: truncateSourceMarkdown(markdown),
    to: toPosition
  };
}

function truncateSourceMarkdown(markdown: string) {
  if (markdown.length <= maxSelectionSourceChars) return markdown;

  return `${markdown.slice(0, maxSelectionSourceChars).trimEnd()}\n...`;
}

export function formatHeadingMarkdown(heading: AiHeadingAnchor) {
  const level = Math.min(6, Math.max(1, Math.trunc(heading.level || 1)));
  return `${"#".repeat(level)} ${heading.title}`;
}

function normalizeSelectionText(value: string) {
  return value.replace(/\s+/g, " ").trim();
}

function clampSourcePosition(value: number | undefined, docSize: number) {
  if (typeof value !== "number" || Number.isNaN(value)) return null;

  return Math.min(docSize, Math.max(0, value));
}

